import { readFileSync, writeFileSync } from "node:fs"

const [input, output, version] = process.argv.slice(2)
if (!input || !output || !version) throw new Error("usage: patch-marked.ts <input> <output> <version>")

// Approximates \p{P}\p{S} with ASCII punctuation plus common Unicode punctuation blocks.
const punctuation = String.raw`!-\/:-@\[-\u0060{-~\u00A1-\u00BF\u2010-\u2027\u2030-\u205E\u3001-\u3003`
let source = readFileSync(input, "utf8")
source = source.replaceAll(String.raw`[\p{L}\p{N}]`, String.raw`[A-Za-z0-9\u00C0-\uFFFF]`)
source = source.replaceAll(String.raw`\p{P}\p{S}`, punctuation)
// The Unicode flag is no longer needed once the classes above are explicit.
source = source.replace(/(\/[^\n]*\])(\)?)\/u([,;])/g, "$1$2/$3")
if (source.includes(String.raw`\p{`)) throw new Error("unsupported Unicode property escape remains")

const header = `// Generated by build-marked.sh from marked@${version} (MIT). Do not edit.
.pragma library
if (!Array.prototype.at) Array.prototype.at = function(i) { i = Math.trunc(i) || 0; if (i < 0) i += this.length; return this[i] }
if (!String.prototype.at) String.prototype.at = function(i) { i = Math.trunc(i) || 0; if (i < 0) i += this.length; return this.charAt(i) }
if (!String.prototype.trimEnd) String.prototype.trimEnd = function() { return this.replace(/\\s+$/, "") }
if (!String.prototype.trimStart) String.prototype.trimStart = function() { return this.replace(/^\\s+/, "") }
if (!Array.prototype.flat) Array.prototype.flat = function(depth) {
  const d = depth === undefined ? 1 : depth
  return this.reduce((out, item) => out.concat(Array.isArray(item) && d > 0 ? item.flat(d - 1) : [item]), [])
}
`
writeFileSync(output, `${header}${source}\nfunction api() { return marked }\n`)
